1	(* enumerate_truth.wl
2	   Phase 2 of the truth-enumeration plan: per (p, q) in the empirically
3	   reachable grid, run the streaming enumerator, compute per-iso-class
4	   statistics and the three exact distributions (vertex-labeled,
5	   facet-labeled, unlabeled), and persist a single WXF cache per cell.
6	
7	   Reachable grid (from docs/enumeration_scaling.md):
8	     {(2, 4), (2, 5), (2, 6), (3, 4), (3, 5)}.
9	
10	   Output: data/p{p}q{q}_truth.wxf, schema:
11	     <|
12	       "p" -> p, "q" -> q,
13	       "numIsoClasses"     -> Length[isoReps],
14	       "totalFacetLabeled" -> sr["totalEmitted"],
15	       "numBuckets"        -> sr["numBuckets"],
16	       "complexes"         -> {<|"facets"->..., "aut"->..., "autF"->...,
17	                                 "nV"->..., "stats"-><|...|>|>, ...},
18	       "piVertex"          -> {N, ...},     (* normalized π_V over iso classes *)
19	       "piFacet"           -> {N, ...},     (* normalized π_F over iso classes *)
20	       "piUnlabeled"       -> {N, ...},     (* uniform 1/numIsoClasses *)
21	       "wallClockSec"      -> ...,
22	       "peakMemMB"         -> ...,
23	       "ecGravVersion"     -> "1.0.0",
24	       "enumeratorVersion" -> "streaming_enumerator.wl@<sha>",
25	       "createdAt"         -> ...|>
26	
27	   Idempotent: skips cells whose WXF already exists and is non-empty.
28	   Force-recompute via env var COMB_FORCE=1.
29	   Restrict cells via env var COMB_TRUTH_CELLS="p,q;p,q;..." (default:
30	   the full reachable grid).
31	
32	   Validation gates (per docs/PLAN_TRUTH_ENUMERATION.md): iso-class
33	   counts must match {(2,4)->11, (2,5)->26, (2,6)->68, (3,4)->66,
34	   (3,5)->445}. Mismatch aborts the run. *)
35	
36	Needs["ECGrav`"];
37	
38	scriptDir = If[ValueQ[$InputFileName] && $InputFileName =!= "",
39	  DirectoryName[$InputFileName], Directory[]];
40	projectRoot = ParentDirectory[scriptDir];
41	outputDir = FileNameJoin[{projectRoot, "data"}];
42	If[!DirectoryQ[outputDir], CreateDirectory[outputDir]];
43	
44	(* ===== Load streaming enumerator ===== *)
45	Get[FileNameJoin[{scriptDir, "streaming_enumerator.wl"}]];
46	
47	(* ===== Pull statsFor + helpers from pure_simplicial_compute.wl =====
48	   The Get'd script also runs a per-p sampling loop on load; suppress it
49	   by passing pListOverride = {} so the loop is a no-op. Definitions
50	   (oneSkeleton, statsFor, etc.) persist after Block returns because
51	   Block scopes only the OwnValues of the listed symbols. *)
52	Block[{pListOverride = {}, sampleSizeOverride = 0,
53	       useParallelOverride = False},
54	  Get[FileNameJoin[{scriptDir, "pure_simplicial_compute.wl"}]]];
55	
56	(* ===== Cells + expected iso-class counts (validation gates) ===== *)
57	defaultCells = {{2, 4}, {2, 5}, {2, 6}, {3, 4}, {3, 5}};
58	expectedIsoCounts = <|
59	  {2, 4} -> 11, {2, 5} -> 26, {2, 6} -> 68,
60	  {3, 4} -> 66, {3, 5} -> 445|>;
61	
62	parseEnvCells[s_String] := Module[{pairs},
63	  pairs = StringSplit[StringTrim[s], ";"];
64	  pairs = StringSplit[#, ","] & /@ pairs;
65	  ToExpression /@ # & /@ pairs];
66	
67	resolvedCells = Which[
68	  StringQ[Environment["COMB_TRUTH_CELLS"]] &&
69	    StringLength[Environment["COMB_TRUTH_CELLS"]] > 0,
70	    parseEnvCells[Environment["COMB_TRUTH_CELLS"]],
71	  True, defaultCells];
72	
73	forceRecompute = With[{e = Environment["COMB_FORCE"]},
74	  StringQ[e] && e === "1"];
75	
76	(* ===== Provenance ===== *)
77	ecGravVersion = "1.0.0";  (* vendored at ECGrav/ECGrav-1.0.0/ *)
78	enumeratorVersion = Module[{res, sha},
79	  res = Quiet @ RunProcess[{
80	    "git", "-C", projectRoot, "rev-parse", "--short", "HEAD"}];
81	  If[AssociationQ[res] && res["ExitCode"] === 0,
82	    sha = StringTrim[res["StandardOutput"]];
83	    "streaming_enumerator.wl@" <> sha,
84	    "streaming_enumerator.wl@unknown"]];
85	
86	Print["scriptDir         = ", scriptDir];
87	Print["outputDir         = ", outputDir];
88	Print["resolvedCells     = ", resolvedCells];
89	Print["forceRecompute    = ", forceRecompute];
90	Print["ecGravVersion     = ", ecGravVersion];
91	Print["enumeratorVersion = ", enumeratorVersion];
92	
93	(* ===== Per-cell pipeline ===== *)
94	truthFile[p_Integer, q_Integer] := FileNameJoin[{outputDir,
95	  "p" <> ToString[p] <> "q" <> ToString[q] <> "_truth.wxf"}];
96	
97	statsHeaders = {"numV", "aut", "autF", "connected",
98	  "num1VConnComps", "num2VConnComps", "largestCompRatio",
99	  "num2PathConnComps", "num3PathConnComps",
100	  "Betti1", "Betti2", "Betti3"};
101	
102	exportWxfAtomic[path_String, expr_] := Module[{tmp, res},
103	  tmp = path <> ".tmp";
104	  If[FileExistsQ[tmp], DeleteFile[tmp]];
105	  Export[tmp, expr, "WXF"];
106	  If[!FileExistsQ[tmp],
107	    Print["    ERROR: tmp not written: ", tmp]; Abort[]];
108	  If[FileExistsQ[path], DeleteFile[path]];
109	  res = RenameFile[tmp, path];
110	  If[res === $Failed,
111	    Print["    ERROR: rename failed ", tmp, " -> ", path]; Abort[]]];
112	
113	processCell[{p_Integer, q_Integer}] := Module[
114	  {outFile, expectedIso, sr, wallSec, peakMemMB, isoReps, nIso,
115	   complexEntries, piV, piF, piU, statsTime, payload, vWeights, fWeights},
116	
117	  outFile = truthFile[p, q];
118	  expectedIso = Lookup[expectedIsoCounts, Key[{p, q}], Missing[]];
119	
120	  Print[""];
121	  Print["====================================="];
122	  Print["(p, q) = (", p, ", ", q, ")  -->  ", FileNameTake[outFile]];
123	  If[!MissingQ[expectedIso],
124	    Print["  expected |iso|: ", expectedIso],
125	    Print["  expected |iso|: (no gate registered for this cell)"]];
126	
127	  If[FileExistsQ[outFile] && FileByteCount[outFile] > 0 && !forceRecompute,
128	    Print["  WXF already exists (", Round[FileByteCount[outFile]/1024., 0.1],
129	      " KB), skipping. Set COMB_FORCE=1 to override."];
130	    Return[]];
131	
132	  (* ----- Streaming enumeration ----- *)
133	  ClearSystemCache[];
134	  {wallSec, sr} = AbsoluteTiming[
135	    streamingEnumeratePure[p, q, Parallel -> True]];
136	  peakMemMB = N[MaxMemoryUsed[] / 2.0^20];
137	
138	  isoReps = sr["isoReps"];
139	  nIso = Length[isoReps];
140	
141	  Print["  streaming done in ", Round[wallSec, 0.01], "s,",
142	    "   peak mem ", Round[peakMemMB, 0.1], " MB"];
143	  Print["  |isoReps|     = ", nIso];
144	  Print["  totalEmitted  = ", sr["totalEmitted"]];
145	  Print["  numBuckets    = ", sr["numBuckets"]];
146	
147	  (* ----- Validation gate ----- *)
148	  If[!MissingQ[expectedIso],
149	    If[nIso =!= expectedIso,
150	      Print["  *** FAIL: |isoReps| ", nIso,
151	            " != expected ", expectedIso, " ***"];
152	      Abort[],
153	      Print["  ok: iso-class count matches expected ", expectedIso]]];
154	
155	  (* ----- Per-iso-class stats ----- *)
156	  Print["  computing 12-stat row for ", nIso, " iso classes ..."];
157	  {statsTime, complexEntries} = AbsoluteTiming[
158	    Table[
159	      With[{cmplx = isoReps[[i]]},
160	        Module[{statsAssoc},
161	          statsAssoc = AssociationThread[
162	            statsHeaders -> statsFor[cmplx, p]];
163	          <|"facets" -> cmplx,
164	            "aut"   -> statsAssoc["aut"],
165	            "autF"  -> statsAssoc["autF"],
166	            "nV"    -> statsAssoc["numV"],
167	            "stats" -> statsAssoc|>]],
168	      {i, nIso}]];
169	  Print["    stats time  : ", Round[statsTime, 0.01], "s"];
170	
171	  (* ----- Exact distributions over iso classes -----
172	     π_V(X) ∝ nV(X)! / aut(X)
173	     π_F(X) ∝ q!     / autF(X)
174	     π_U(X) ∝ 1
175	     Use exact rationals for the unnormalized weights, then convert to
176	     machine reals at the very end. *)
177	  vWeights = (#["nV"]! / #["aut"]) & /@ complexEntries;
178	  fWeights = (q! / #["autF"]) & /@ complexEntries;
179	  piV = N[vWeights / Total[vWeights]];
180	  piF = N[fWeights / Total[fWeights]];
181	  piU = ConstantArray[N[1/nIso], nIso];
182	
183	  (* Sanity: distributions sum to 1 within float tolerance. *)
184	  MapThread[
185	    Function[{d, name}, With[{s = Total[d]},
186	      If[Abs[s - 1.0] > 1.0*^-9,
187	        Print["    WARNING: ", name, " sum is ", s, " (expected 1.0)"]]]],
188	    {{piV, piF, piU}, {"piVertex", "piFacet", "piUnlabeled"}}];
189	
190	  (* ----- Persist ----- *)
191	  payload = <|
192	    "p" -> p, "q" -> q,
193	    "numIsoClasses"     -> nIso,
194	    "totalFacetLabeled" -> sr["totalEmitted"],
195	    "numBuckets"        -> sr["numBuckets"],
196	    "complexes"         -> complexEntries,
197	    "piVertex"          -> piV,
198	    "piFacet"           -> piF,
199	    "piUnlabeled"       -> piU,
200	    "wallClockSec"      -> wallSec,
201	    "peakMemMB"         -> peakMemMB,
202	    "ecGravVersion"     -> ecGravVersion,
203	    "enumeratorVersion" -> enumeratorVersion,
204	    "createdAt"         -> DateString[]|>;
205	
206	  exportWxfAtomic[outFile, payload];
207	  Print["  wrote ", FileNameTake[outFile],
208	    "  (", Round[FileByteCount[outFile] / 1024., 0.1], " KB)"]];
209	
210	(* ===== Driver ===== *)
211	Do[processCell[cell], {cell, resolvedCells}];
212	
213	Print[""];
214	Print["====================================="];
215	Print["Done."];
