1	(* render_all_figures.wl
2	   Renders Figures 3-15 from p{2,3,4}q10_merged_stats.wxf (in ../data/).
3	   Three panel modes — all rendered as TRANSLUCENT OVERLAID histograms
4	   (matching paper Figure 2 style), not grouped bars:
5	     "discrete"     — Histogram with bin width 1, integer x values
6	     "logdiscrete"  — Histogram of Log10[val], one bin per decade, 10^k tick labels
7	     "continuous"   — Histogram with Automatic bins
8	   Outputs:
9	     ../figures/stacked_previews/fig{03..15}_*.{pdf,png}   (one stacked column per fig)
10	     ../figures/manuscript_panels/p{p}q10[conn]SX{Stat}_merged.pdf (~30 panels)
11	     ../figures/combined_all_figures_merged.pdf            (multi-page combined)
12	   Prints per-p ESS at startup. *)
13	
14	(* ===== paths ===== *)
15	projectRoot = ParentDirectory[
16	  If[ValueQ[$InputFileName] && $InputFileName =!= "",
17	    DirectoryName[$InputFileName], Directory[]]];
18	dataDir             = FileNameJoin[{projectRoot, "data"}];
19	figuresDir          = FileNameJoin[{projectRoot, "figures"}];
20	stackedPreviewsDir  = FileNameJoin[{figuresDir, "stacked_previews"}];
21	manuscriptPanelsDir = FileNameJoin[{figuresDir, "manuscript_panels"}];
22	
23	If[!DirectoryQ[stackedPreviewsDir],  CreateDirectory[stackedPreviewsDir]];
24	If[!DirectoryQ[manuscriptPanelsDir], CreateDirectory[manuscriptPanelsDir]];
25	
26	Print["projectRoot         = ", projectRoot];
27	Print["dataDir             = ", dataDir];
28	Print["figuresDir          = ", figuresDir];
29	
30	(* ===== parameters ===== *)
31	qVal = 10;
32	pList = {2, 3, 4};
33	sampleSize = 12000000;  (* informational only — stem reads merged file directly *)
34	sampleTag  = "merged";
35	
36	(* ===== style ===== *)
37	colorVertex    = RGBColor[0.984, 0.757, 0.369];
38	colorFacet     = RGBColor[0.122, 0.471, 0.706];
39	colorUnlabeled = RGBColor[0.890, 0.290, 0.200];
40	seriesColorsTrans = {
41	  Directive[colorVertex,    Opacity[0.55], EdgeForm[Directive[colorVertex,    AbsoluteThickness[0.4]]]],
42	  Directive[colorFacet,     Opacity[0.55], EdgeForm[Directive[colorFacet,     AbsoluteThickness[0.4]]]],
43	  Directive[colorUnlabeled, Opacity[0.55], EdgeForm[Directive[colorUnlabeled, AbsoluteThickness[0.4]]]]};
44	seriesNames = {"vertex-labeled", "facet-labeled", "unlabeled"};
45	legendSwatches = {colorVertex, colorFacet, colorUnlabeled};
46	
47	frameOpts = Sequence[
48	  Frame -> True,
49	  FrameStyle -> Directive[Black, AbsoluteThickness[1]],
50	  LabelStyle -> Directive[FontFamily -> "Times", FontSize -> 11, Black],
51	  ImageSize -> {360, 270},
52	  PlotRange -> All,
53	  ImageMargins -> 5];
54	
55	panelLabel[p_] := Style["p = " <> ToString[p],
56	  FontFamily -> "Times", FontSize -> 12, Bold];
57	
58	(* ===== load =====
59	   Prefers WXF (fast, typed). Falls back to legacy CSV if no WXF present. *)
60	stem[p_] := "p" <> ToString[p] <> "q" <> ToString[qVal] <> "_merged";
61	
62	loadSamplesWXF[path_] := Module[{a, headers, rows},
63	  Print["  loading ", FileNameTake[path], " (WXF)"];
64	  a = Import[path, "WXF"];
65	  headers = Lookup[a, "headers"];
66	  rows    = Lookup[a, "rows"];
67	  AssociationThread[headers -> Transpose[rows]]];
68	
69	loadSamplesCSV[path_] := Module[{raw, headers, body, cols, parseCol},
70	  Print["  loading ", FileNameTake[path], " (CSV, legacy)"];
71	  raw = Import[path, "CSV"];
72	  headers = First[raw];
73	  body = Rest[raw];
74	  cols = Transpose[body];
75	  parseCol[col_] := Map[Function[x, Which[
76	    x === "", Missing[],
77	    StringQ[x], N[ToExpression[x]],
78	    True, x]], col];
79	  AssociationThread[headers -> (parseCol /@ cols)]];
80	
81	loadSamples[p_] := Module[{wxf, csv},
82	  wxf = FileNameJoin[{dataDir, stem[p] <> "_stats.wxf"}];
83	  csv = FileNameJoin[{dataDir, stem[p] <> "_samples.csv"}];
84	  Which[
85	    FileExistsQ[wxf], loadSamplesWXF[wxf],
86	    FileExistsQ[csv], loadSamplesCSV[csv],
87	    True, Print["  ERROR: no data for p=", p]; Abort[]]];
88	
89	Print["----- loading samples -----"];
90	sampleData = AssociationMap[loadSamples, pList];
91	
