1	(* sampler_mh.wl
2	   Exploratory Metropolis-Hastings sampler over isomorphism classes of pure
3	   simplicial complexes (q facets, purity p).
4	
5	   STATUS: prototype. Math reviewed and small-example-verified (p=2 q=2 on
6	   [N=4] gives uniform iso-class marginal, see comments below). NOT
7	   benchmarked vs IS at q=10, NOT in the production pipeline. Written
8	   2026-04-29 in response to docs/email_betre_post_batch3.md item 1, pending
9	   Dr. Betre's reply. See docs/PIPELINE.md for the IS sampler this is
10	   trying to replace at q=10 p∈{3,4}.
11	
12	   ============================================================================
13	   PRIOR ATTEMPT (replaced by this file 2026-04-29)
14	   ============================================================================
15	   First draft canonicalized state to "vertex labels in first-appearance order,
16	   no unused labels." That broke detailed balance: the canonicalization
17	   collapses different vertex-labelings of the same iso class to a variable
18	   number of canonical forms (e.g. for the (p=2,q=2) path iso class, 3
19	   labelings collapse to 2 canonical forms; for "two disjoint edges," 3
20	   labelings collapse to 1). This makes P_marg([iso class]) ∝ 1/c([Y]) where
21	   c is an irregular collapse factor. Empirically the chain at p=4 q=10
22	   reported E[numV] ≈ 10 vs true π_U mode ~18 (verified via IS at 12M).
23	
24	   This rewrite uses a FIXED ambient label set [N] with N = q·p (the maximum
25	   possible numV for a pure complex with q facets at purity p). Every state
26	   is a vertex-labeled complex on a subset of [N]; "unused" labels are simply
27	   not in any facet. Detailed balance holds without canonicalization.
28	
29	   ============================================================================
30	   STATE
31	   ============================================================================
32	   A state is a sorted list of q distinct sorted p-element subsets of [N],
33	   where N = q·p. The active vertex set V(X) = ⋃ F_i ⊆ [N]. numV(X) = |V(X)|.
34	
35	   ============================================================================
36	   TARGETS
37	   ============================================================================
38	     unlabeled (uniform on iso classes):
39	       π_U(X) ∝ |Aut(X)| · (N - numV(X))!
40	     facet (uniform on facet-labelings, marginal on iso classes):
41	       π_F(X) ∝ |Aut(X)| · (N - numV(X))! / |Aut_F(X)|
42	     vertex (uniform on vertex-labeled, sanity check):
43	       π_V(X) ∝ 1
44	
45	   Verification of unlabeled target via marginal calculation:
46	     For iso class [Y] with numV([Y]) = k, the number of vertex-labeled
47	     states on [N] with iso class [Y] is C(N, k) · k!/|Aut(Y)|. Each such
48	     state has π_U ∝ |Aut(Y)| · (N-k)!. So
49	       π_U_marg([Y]) ∝ C(N,k) · k!/|Aut(Y)| · |Aut(Y)| · (N-k)! = N!.
50	     Constant in [Y]. ✓ Uniform on iso classes.
51	
52	   Hand-verified small example (p=2, q=2, N=4):
53	     iso "path" (numV=3, |Aut|=2): 12 states · 2·1! = 24 total mass.
54	     iso "matching" (numV=4, |Aut|=8): 3 states · 8·0! = 24 total mass.
55	     Equal. ✓
56	
57	   ============================================================================
58	   PROPOSAL
59	   ============================================================================
60	   From X with active set V(X) ⊆ [N]:
61	     1. Pick i ∈ {1,...,q} uniformly.
62	     2. Pick F' uniformly from p-subsets of [N] not equal to any F_j (j ≠ i).
63	     3. Form Y as X with F_i replaced by F', then re-sort.
64	   Proposal density q(X→Y) = (1/q) · 1/(C(N,p) - (q-1)). Symmetric in (X,Y).
65	
66	   ============================================================================
67	   ACCEPTANCE RATIO
68	   ============================================================================
69	   With symmetric proposal:
70	     α(X→Y) = min(1, π(Y)/π(X))
71	
72	   For target unlabeled:
73	     π(Y)/π(X) = [|Aut(Y)|/|Aut(X)|] · [(N-numV(Y))!/(N-numV(X))!]
74	   For target facet:
75	     π(Y)/π(X) = [|Aut(Y)|/|Aut(X)|]
76	                 · [|Aut_F(X)|/|Aut_F(Y)|]
77	                 · [(N-numV(Y))!/(N-numV(X))!]
78	   For target vertex:
79	     π(Y)/π(X) = 1   (chain reduces to RW on vertex-labeled states)
80	
81	   Factorial ratio (N-mY)!/(N-m)! depends on Δm = mY - m ∈ {-p, ..., p}:
82	     Δm =  0  →  1
83	     Δm = +1  →  1/(N-m)
84	     Δm = +2  →  1/((N-m)(N-m-1))
85	     Δm = -1  →  N-m+1
86	     etc. Bounded by polynomial factor in N.
87	*)
88	
89	Needs["ECGrav`"];
90	
91	(* =============================================================== *)
92	(* Helpers                                                          *)
93	(* =============================================================== *)
94	
95	numActive[facets_List] := Length[DeleteDuplicates[Flatten[facets]]];
96	
97	(* Sample a uniform random p-subset of [N] excluding the supplied list.
98	   Rejection sampling. *)
99	randomSubsetExcluding[n_Integer, p_Integer, forbidden_List] := Module[
100	  {F, attempts = 0, maxAttempts = 1000},
101	  While[attempts < maxAttempts,
102	    F = Sort[RandomSample[Range[n], p]];
103	    If[!MemberQ[forbidden, F], Return[F]];
104	    attempts++];
105	  RandomChoice[Complement[Subsets[Range[n], {p}], forbidden]]];
106	
107	(* For computing |Aut| we hand the chain state straight to the ECGrav
108	   functions. They operate on facet lists over arbitrary integer labels;
109	   the value of |Aut| is iso-invariant so the choice of labels doesn't
110	   matter. *)
111	
112	(* ===============================================================
113	   Proposal kernels (added 2026-04-29).
114	
115	   All proposals are SYMMETRIC: q(X→Y) = q(Y→X). With symmetric q,
116	   Metropolis acceptance simplifies to min(1, π(Y)/π(X)).
117	
118	   Each kernel returns {Y, deltaNumActive} — the proposed state and
119	   the change in numActive (0 for no-op).
120	
121	   Benchmark results at p=4 q=10 / p=2 q=4 are summarized in
122	   docs/NEXT.md; tl;dr "global" remains the best for numV-mixing,
123	   "mixed" is comparable on accuracy and ~26% faster wall-clock.
124	   =============================================================== *)
125	
126	proposeGlobal[X_List, p_Integer, q_Integer, nMax_Integer] := Module[
127	  {i, otherFacets, Fnew, Y, mOld},
128	  mOld = numActive[X];
129	  i = RandomInteger[{1, q}];
130	  otherFacets = Delete[X, i];
131	  Fnew = randomSubsetExcluding[nMax, p, otherFacets];
132	  Y = Sort[ReplacePart[X, i -> Fnew]];
133	  {Y, numActive[Y] - mOld}];
134	
135	(* Local: change one vertex in one facet. Symmetric. *)
136	proposeLocal[X_List, p_Integer, q_Integer, nMax_Integer] := Module[
137	  {i, j, vNew, Fi, FNew, Y, mOld},
138	  mOld = numActive[X];
139	  i = RandomInteger[{1, q}];
140	  j = RandomInteger[{1, p}];
141	  vNew = RandomInteger[{1, nMax}];
142	  Fi = X[[i]];
143	  If[MemberQ[Fi, vNew], Return[{X, 0}]];
144	  FNew = Sort[ReplacePart[Fi, j -> vNew]];
145	  If[MemberQ[Delete[X, i], FNew], Return[{X, 0}]];
146	  Y = Sort[ReplacePart[X, i -> FNew]];
147	  {Y, numActive[Y] - mOld}];
148	
149	(* Swap: exchange one vertex between two facets. Symmetric.
150	   WARNING: when used as the sole kernel, ergodicity is poor — at p=2
151	   most swaps yield states in the same iso class as the input. Useful
152	   only as a component of a mixture. *)
153	proposeSwap[X_List, p_Integer, q_Integer, nMax_Integer] := Module[
154	  {i, k, j, l, a, b, Fi, Fk, FiNew, FkNew, otherFacets, Y, mOld},
155	  mOld = numActive[X];
156	  i = RandomInteger[{1, q}];
157	  k = RandomInteger[{1, q - 1}];
158	  If[k >= i, k = k + 1];
159	  j = RandomInteger[{1, p}];
160	  l = RandomInteger[{1, p}];
161	  Fi = X[[i]]; Fk = X[[k]];
162	  a = Fi[[j]]; b = Fk[[l]];
163	  Which[
164	    a === b,        Return[{X, 0}],
165	    MemberQ[Fi, b], Return[{X, 0}],
166	    MemberQ[Fk, a], Return[{X, 0}]];
167	  FiNew = Sort[ReplacePart[Fi, j -> b]];
168	  FkNew = Sort[ReplacePart[Fk, l -> a]];
169	  If[FiNew === FkNew, Return[{X, 0}]];
170	  otherFacets = Delete[X, {{i}, {k}}];
171	  If[MemberQ[otherFacets, FiNew] || MemberQ[otherFacets, FkNew],
172	    Return[{X, 0}]];
173	  Y = Sort[ReplacePart[X, {i -> FiNew, k -> FkNew}]];
174	  {Y, numActive[Y] - mOld}];
175	
176	(* Mixed: 50% local + 30% swap + 20% global. *)
177	proposeMixed[X_List, p_Integer, q_Integer, nMax_Integer,
178	             alphaLocal_:0.5, betaSwap_:0.3] := Module[{u},
179	  u = RandomReal[];
180	  Which[
181	    u < alphaLocal,            proposeLocal[X, p, q, nMax],
182	    u < alphaLocal + betaSwap, proposeSwap[X, p, q, nMax],
183	    True,                      proposeGlobal[X, p, q, nMax]]];
184	
185	(* =============================================================== *)
186	(* MH step                                                          *)
187	(* =============================================================== *)
188	
189	(* Returns {newState, acceptedQ, ΔnumV, alpha}.
190	   nMax (rather than N) to avoid shadowing built-in N (numerical conversion).
191	   kernel ∈ {"global", "local", "swap", "mixed"} selects the proposal kernel. *)
192	mhStep[X_List, p_Integer, q_Integer, nMax_Integer, target_String,
193	       kernel_String:"global"] := Module[
194	  {m, mY, Y, deltaM,
195	   autX, autY, autFX, autFY, factRatio, piRatio, alpha, u},
196	
197	  m = numActive[X];
198	  {Y, deltaM} = Switch[kernel,
199	    "global", proposeGlobal[X, p, q, nMax],
200	    "local",  proposeLocal[X, p, q, nMax],
201	    "swap",   proposeSwap[X, p, q, nMax],
202	    "mixed",  proposeMixed[X, p, q, nMax],
203	    _, Print["unknown kernel: ", kernel]; Abort[]];
204	
205	  (* If the proposal degenerated to a no-op (Y == X), accept trivially. *)
206	  If[Y === X, Return[{X, True, 0, 1.0}]];
207	
208	  mY = m + deltaM;
209	
210	  (* (nMax-mY)!/(nMax-m)! computed safely for any Δm ∈ [-p, p]. *)
211	  factRatio = Which[
212	    deltaM == 0, 1,
213	    deltaM > 0,  1 / Product[nMax - m - j, {j, 0, deltaM - 1}],
214	    deltaM < 0,  Product[nMax - mY - j, {j, 0, -deltaM - 1}]];
215	
216	  Switch[target,
217	    "unlabeled",
218	      autX = PureComplexAutomorphismGroupOrder[X];
219	      autY = PureComplexAutomorphismGroupOrder[Y];
220	      piRatio = (autY / autX) * factRatio,
221	    "facet",
222	      autX  = PureComplexAutomorphismGroupOrder[X];
223	      autY  = PureComplexAutomorphismGroupOrder[Y];
224	      autFX = PureComplexFacetAutomorphismGroupOrder[X];
225	      autFY = PureComplexFacetAutomorphismGroupOrder[Y];
226	      piRatio = (autY / autX) * (autFX / autFY) * factRatio,
227	    "vertex",
228	      piRatio = 1,
229	    _,
230	      Print["unknown target: ", target]; Abort[]];
231	
232	  alpha = Min[1, N[piRatio]];
233	  u = RandomReal[];
234	  If[u < alpha,
235	    {Y, True, deltaM, alpha},
236	    {X, False, deltaM, alpha}]
237	];
238	
239	(* =============================================================== *)
240	(* Initialization                                                   *)
241	(* =============================================================== *)
242	
243	(* Embed a vertex-labeled sample (active labels in {1..k}) into [nMax] as the
244	   first k labels. Other labels in [nMax] are unused. *)
245	initialState[p_Integer, q_Integer, nMax_Integer, seed_Integer] := Module[
246	  {complex, sorted},
247	  SeedRandom[seed];
248	  complex = First[RandomVertexLabeledPureSimplicialComplex[{p, q}, 1]];
249	  sorted = Sort[Sort /@ complex];
250	  sorted];
251	
252	(* =============================================================== *)
253	(* Chain runner                                                     *)
254	(* =============================================================== *)
255	
256	Options[runMHChain] = {burnIn -> 0, thin -> 1, seed -> 12345,
257	  verbose -> True, kernel -> "global"};
258	
259	runMHChain[p_Integer, q_Integer, target_String, numIter_Integer,
260	           opts:OptionsPattern[]] := Module[
261	  {bIn, th, sd, vrb, kn, NN, X, traceLen, trace, accepts = 0, deltas,
262	   step, idx, t0, t1},
263	
264	  bIn = OptionValue[burnIn];
265	  th  = OptionValue[thin];
266	  sd  = OptionValue[seed];
267	  vrb = OptionValue[verbose];
268	  kn  = OptionValue[kernel];
269	
270	  NN = q * p;
271	  X  = initialState[p, q, NN, sd];
272	
273	  If[vrb,
274	    Print["MH chain: p=", p, " q=", q, " nMax=", NN,
275	      " target=", target, " kernel=", kn,
276	      " numIter=", numIter, " burnIn=", bIn, " thin=", th]];
277	
278	  t0 = AbsoluteTime[];
279	
280	  (* Burn-in. *)
281	  Do[
282	    step = mhStep[X, p, q, NN, target, kn];
283	    X = step[[1]];
284	    If[step[[2]], accepts++],
285	    {bIn}];
286	  If[vrb && bIn > 0,
287	    Print["  burn-in done: ", bIn, " steps, accept rate ",
288	      ToString[NumberForm[N[accepts/bIn], {4, 3}]]]];
289	
290	  (* Sampling. *)
291	  accepts = 0;
292	  deltas = ConstantArray[0, numIter];
293	  traceLen = Quotient[numIter, th];
294	  trace = ConstantArray[Null, traceLen];
295	  idx = 0;
296	  Do[
297	    step = mhStep[X, p, q, NN, target, kn];
298	    X = step[[1]];
299	    If[step[[2]], accepts++];
300	    deltas[[k]] = step[[3]];
301	    If[Mod[k, th] == 0,
302	      idx++;
303	      trace[[idx]] = X],
304	    {k, numIter}];
305	
306	  t1 = AbsoluteTime[];
307	
308	  If[vrb,
309	    Print["  sampling done: ", numIter, " steps in ",
310	      ToString[NumberForm[t1 - t0, {6, 1}]], " s"];
311	    Print["    accept rate    : ",
312	      ToString[NumberForm[N[accepts/numIter], {4, 3}]]];
313	    Print["    Δ numV counts  : ", Counts[deltas]];
314	    Print["    trace length   : ", traceLen]];
315	
316	  <|
317	    "p" -> p, "q" -> q, "N" -> NN, "target" -> target,
318	    "numIter" -> numIter, "burnIn" -> bIn, "thin" -> th, "seed" -> sd,
319	    "trace" -> trace,
320	    "acceptRate" -> N[accepts/numIter],
321	    "deltaNumVCounts" -> Counts[deltas],
322	    "wallSeconds" -> (t1 - t0)
323	  |>
324	];
325	
326	(* =============================================================== *)
327	(* Diagnostic: integrated autocorrelation time                      *)
328	(* =============================================================== *)
329	
330	integratedAutocorrTime[x_List] := Module[{n, mu, var, c, k, sum},
331	  n = Length[x];
332	  mu = Mean[N[x]];
333	  var = Variance[N[x]];
334	  If[var == 0., Return[<|"tau" -> Infinity, "ess" -> 0|>]];
335	  sum = 0.5;
336	  k = 1;
337	  While[k < n - 1,
338	    c = Mean[(x[[1 ;; n - k]] - mu) * (x[[1 + k ;; n]] - mu)] / var;
339	    If[c <= 0, Break[]];
340	    sum += c;
341	    k++];
342	  <|"tau" -> sum, "ess" -> N[n / (2 sum)], "lagsUsed" -> k|>
343	];
344	
345	(* =============================================================== *)
346	(* Smoke test main                                                  *)
347	(* =============================================================== *)
348	
349	If[$InputFileName =!= "" && !TrueQ[$smokeTestSkip],
350	  Module[{result, numVTrace, ac},
351	    Do[
352	      Print["==========================================="];
353	      result = runMHChain[p, 10, "unlabeled", 5000, burnIn -> 1000];
354	      numVTrace = numActive /@ result["trace"];
355	      ac = integratedAutocorrTime[numVTrace];
356	      Print["    τ_int(numV)   : ",
357	        ToString[NumberForm[ac["tau"], {6, 2}]],
358	        "  (lagsUsed=", ac["lagsUsed"], ")"];
359	      Print["    effective N   : ", Round[ac["ess"]],
360	        " of ", Length[numVTrace]];
361	      Print["    numV mean/std : ",
362	        ToString[NumberForm[Mean[N[numVTrace]], {5, 2}]], " / ",
363	        ToString[NumberForm[StandardDeviation[N[numVTrace]], {5, 2}]]],
364	      {p, {2, 3, 4}}];
365	    Print["==========================================="];
366	    Print["smoke test done."]]];
367

