1	(* pure_simplicial_compute.wl
2	   Sampling + per-sample statistics pipeline for Figures 3-16.
3	   Pure simplicial complexes, q = 10, p in {2, 3, 4}.
4	   Produces two WXF files per p per session:
5	     {stem}_stats.wxf     — Association with headers, rows, metadata (stats + weights)
6	     {stem}_complexes.wxf — Association with the raw sampled complexes
7	   Independent of histograms_handoff_v2.nb / histograms_paper_figures.nb. *)
8	
9	Needs["ECGrav`"];
10	
11	(* ===== Parameters ===== *)
12	qVal = 10;
13	pList = If[ValueQ[pListOverride], pListOverride, {2, 3, 4}];
14	sampleSize = If[ValueQ[sampleSizeOverride], sampleSizeOverride, 10000];
15	randomSeed = 123456;
16	
17	(* Optional run tag. When set (e.g. via env var COMB_RUNTAG="batch2") the output
18	   filename becomes p{p}q10_n{N}_{runTag}_samples.csv AND the per-chunk seed is
19	   offset by a deterministic hash of the tag. This lets a fresh run produce
20	   fully independent samples that can be concatenated with a prior run via
21	   concat_samples.wl, without colliding on seeds. *)
22	runTag = If[ValueQ[runTagOverride], runTagOverride,
23	  With[{envTag = Environment["COMB_RUNTAG"]},
24	    If[StringQ[envTag] && StringLength[envTag] > 0, envTag, ""]]];
25	runSeedOffset = If[runTag === "", 0,
26	  Mod[Hash[runTag, "MD5"], 10^7]];
27	
28	(* Output goes to projectRoot/data/  (projectRoot = parent of src/). *)
29	scriptDir = If[ValueQ[$InputFileName] && $InputFileName =!= "",
30	  DirectoryName[$InputFileName], Directory[]];
31	projectRoot = ParentDirectory[scriptDir];
32	outputDir = FileNameJoin[{projectRoot, "data"}];
33	If[!DirectoryQ[outputDir], CreateDirectory[outputDir]];
34	
35	(* Optional ParallelMap over the per-sample stats step.
36	   Activate by setting useParallelOverride = True before Get'ing this script. *)
37	useParallel = If[ValueQ[useParallelOverride], useParallelOverride, False];
38	
39	Print["sampleSize    = ", sampleSize];
40	Print["pList         = ", pList];
41	Print["outputDir     = ", outputDir];
42	Print["useParallel   = ", useParallel];
43	Print["runTag        = ", If[runTag === "", "(none)", runTag]];
44	Print["runSeedOffset = ", runSeedOffset];
45	
46	(* ===== 1-skeleton ===== *)
47	oneSkeleton[c_List] := Module[{verts, edges},
48	  verts = DeleteDuplicates[Flatten[c]];
49	  edges = DeleteDuplicates[Sort /@ Flatten[Subsets[#, {2}] & /@ c, 1]];
50	  Graph[verts, UndirectedEdge @@@ edges]
51	];
52	
53	(* ===== k-path components via k-graph construction =====
54	   Vertices = (k-1)-simplices (size-k subsets of facets).
55	   Edges between two (k-1)-simplices in any common facet.
56	   Number of k-path connected components = #connected components of k-graph. *)
57	kPathComps[c_List, k_Integer] := Module[{faces, edges},
58	  faces = DeleteDuplicates[Sort /@ Flatten[Subsets[#, {k}] & /@ c, 1]];
59	  edges = DeleteDuplicates[
60	    Flatten[Subsets[Sort /@ Subsets[#, {k}], {2}] & /@ c, 1]];
61	  Length[ConnectedComponents[Graph[faces, UndirectedEdge @@@ edges]]]
62	];
63	
64	(* ===== Betti numbers over Z_2 =====
65	   For a pure complex given by its facets:
66	     C_k spanned by the distinct k-simplices (size-(k+1) subsets of facets)
67	     boundary d_k : C_k -> C_{k-1} sends a k-simplex to sum of its codim-1 faces
68	     beta_k = dim C_k - rank d_k - rank d_{k+1}  (mod 2 coefficients) *)
69	simplicesOfDim[c_List, k_Integer] :=
70	  DeleteDuplicates[Sort /@ Flatten[Subsets[#, {k + 1}] & /@ c, 1]];
71	
72	boundaryMatrix[kSimps_List, km1Simps_List] := Module[{idx, entries},
73	  If[kSimps === {} || km1Simps === {},
74	    Return[SparseArray[{}, {Length[km1Simps], Max[Length[kSimps], 1]}]]];
75	  idx = AssociationThread[km1Simps -> Range[Length[km1Simps]]];
76	  entries = Flatten[Table[
77	    With[{s = kSimps[[i]]},
78	      Table[{idx[Sort[Delete[s, j]]], i} -> 1, {j, Length[s]}]],
79	    {i, Length[kSimps]}], 1];
80	  SparseArray[entries, {Length[km1Simps], Length[kSimps]}]
81	];
82	
83	bettiNumber[c_List, k_Integer] := Module[{ck, ckm1, ckp1, rk, rkp1},
84	  ck = simplicesOfDim[c, k];
85	  If[Length[ck] == 0, Return[0]];
86	  ckm1 = If[k == 0, {}, simplicesOfDim[c, k - 1]];
87	  ckp1 = simplicesOfDim[c, k + 1];
88	  rk = If[k == 0 || Length[ckm1] == 0, 0,
89	    MatrixRank[boundaryMatrix[ck, ckm1], Modulus -> 2]];
90	  rkp1 = If[Length[ckp1] == 0, 0,
91	    MatrixRank[boundaryMatrix[ckp1, ck], Modulus -> 2]];
92	  Length[ck] - rk - rkp1
93	];
94	
95	(* ===== Per-sample bundle =====
96	   Returns a fixed-length row; path-k and Betti_k unavailable at given p are "" (empty). *)
97	statsFor[c_List, p_Integer] := Module[
98	  {g, nv, aut, autF, conn, n1v, n2v, lcr, isConn, n2p, n3p, b1, b2, b3},
99	  g = oneSkeleton[c];
100	  nv = VertexCount[g];
101	  aut = PureComplexAutomorphismGroupOrder[c];
102	  autF = PureComplexFacetAutomorphismGroupOrder[c];
103	  conn = ConnectedComponents[g];
104	  n1v = Length[conn];
105	  n2v = Length[KVertexConnectedComponents[g, 2]];
106	  lcr = N[Max[Length /@ conn] / nv];
107	  isConn = If[n1v == 1, 1, 0];
108	  n2p = If[p >= 3, kPathComps[c, 2], ""];
109	  n3p = If[p >= 4, kPathComps[c, 3], ""];
110	  b1 = bettiNumber[c, 1];
111	  b2 = If[p >= 3, bettiNumber[c, 2], ""];
112	  b3 = If[p >= 4, bettiNumber[c, 3], ""];
113	  {nv, aut, autF, isConn, n1v, n2v, lcr, n2p, n3p, b1, b2, b3}
114	];
115	
116	(* ===== Parallel kernel setup (only when useParallel=True) ===== *)
117	If[useParallel,
118	  Print["launching parallel kernels ..."];
119	  LaunchKernels[];
120	  Print["  ", Length[Kernels[]], " kernels active"];
121	  ParallelEvaluate[Needs["ECGrav`"]];
122	  DistributeDefinitions[oneSkeleton, kPathComps, simplicesOfDim,
123	    boundaryMatrix, bettiNumber, statsFor, qVal]];
124	
125	(* ===== Main loop with checkpointing =====
126	   Per-p chunk files `..._chunk_k_{stats,complexes}.wxf` are written atomically
127	   (tmp + rename). A chunk is "done" only when BOTH files are present.
128	   On restart we skip any p whose final stats WXF exists; for a partially-done
129	   p we resume at the first chunk missing either file. At most one chunk
130	   (~11 min on p=4) is redone after a crash. *)
131	
132	headers = {"numV", "aut", "autF", "connected",
133	  "num1VConnComps", "num2VConnComps", "largestCompRatio",
134	  "num2PathConnComps", "num3PathConnComps",
135	  "Betti1", "Betti2", "Betti3",
136	  "wVertex", "wUnlabeled", "wFacet"};
137	
138	chunkSize = If[ValueQ[chunkSizeOverride], chunkSizeOverride, 25000];
139	numChunks = Ceiling[sampleSize / chunkSize];
140	chunkSizeFor[k_] := If[k == numChunks,
141	  sampleSize - (numChunks - 1) * chunkSize, chunkSize];
142	
143	baseStem[p_] := "p" <> ToString[p] <> "q" <> ToString[qVal] <>
144	  "_n" <> ToString[sampleSize] <>
145	  If[runTag === "", "", "_" <> runTag];
146	chunkStatsFile[p_, k_] := FileNameJoin[{outputDir,
147	  baseStem[p] <> "_chunk_" <> ToString[k] <> "_stats.wxf"}];
148	chunkComplexesFile[p_, k_] := FileNameJoin[{outputDir,
149	  baseStem[p] <> "_chunk_" <> ToString[k] <> "_complexes.wxf"}];
150	finalStatsFile[p_] := FileNameJoin[{outputDir,
151	  baseStem[p] <> "_stats.wxf"}];
152	finalComplexesFile[p_] := FileNameJoin[{outputDir,
153	  baseStem[p] <> "_complexes.wxf"}];
154	
155	firstMissingChunk[p_] := Module[{k = 1},
156	  While[k <= numChunks &&
157	      FileExistsQ[chunkStatsFile[p, k]] &&
158	      FileExistsQ[chunkComplexesFile[p, k]],
159	    k++]; k];
160	
161	exportWxfAtomic[path_String, expr_] := Module[{tmp, res},
162	  tmp = path <> ".tmp";
163	  If[FileExistsQ[tmp], DeleteFile[tmp]];
164	  Export[tmp, expr, "WXF"];
165	  If[! FileExistsQ[tmp],
166	    Print["    ERROR: tmp file not written: ", tmp]; Abort[]];
167	  If[FileExistsQ[path], DeleteFile[path]];
168	  res = RenameFile[tmp, path];
169	  If[res === $Failed,
170	    Print["    ERROR: rename failed ", tmp, " -> ", path]; Abort[]]];
171	
172	(* Per-chunk files hold bare lists — the Association wrapper with metadata is
173	   only applied at the final consolidated file. *)
174	exportChunkAtomic[p_, k_, sample_, rows_] := (
175	  exportWxfAtomic[chunkStatsFile[p, k], rows];
176	  exportWxfAtomic[chunkComplexesFile[p, k], sample]);
177	
178	consolidateChunks[p_] := Module[{allRows, allComplexes, n, statsAssoc, complexesAssoc},
179	  allRows      = Join @@ (Import[chunkStatsFile[p, #], "WXF"] & /@ Range[numChunks]);
180	  allComplexes = Join @@ (Import[chunkComplexesFile[p, #], "WXF"] & /@ Range[numChunks]);
181	  n = Length[allRows];
182	  statsAssoc = <|
183	    "headers"   -> headers,
184	    "rows"      -> allRows,
185	    "p"         -> p,
186	    "q"         -> qVal,
187	    "n"         -> n,
188	    "runTag"    -> runTag,
189	    "createdAt" -> DateString[]|>;
190	  complexesAssoc = <|
191	    "complexes" -> allComplexes,
192	    "p"         -> p,
193	    "q"         -> qVal,
194	    "n"         -> n,
195	    "runTag"    -> runTag,
196	    "createdAt" -> DateString[]|>;
197	  exportWxfAtomic[finalStatsFile[p],     statsAssoc];
198	  exportWxfAtomic[finalComplexesFile[p], complexesAssoc];
199	  Do[
200	    DeleteFile[chunkStatsFile[p, k]];
201	    DeleteFile[chunkComplexesFile[p, k]],
202	    {k, numChunks}];
203	  Print["  consolidated ", n, " rows → ",
204	    FileNameTake[finalStatsFile[p]], " + ",
205	    FileNameTake[finalComplexesFile[p]]];
206	  allRows];
207	
208	reportESS[p_, allRows_] := Module[{numVs, auts, autFs, wU, wF, essU, essF},
209	  numVs = allRows[[All, 1]];
210	  auts  = allRows[[All, 2]];
211	  autFs = allRows[[All, 3]];
212	  wU = MapThread[#1 / #2! &, {auts, numVs}];
213	  wF = MapThread[#1 * qVal! / (#2 * #3!) &, {auts, autFs, numVs}];
214	  essU = N[Total[wU]^2 / Total[wU^2]];
215	  essF = N[Total[wF]^2 / Total[wF^2]];
216	  Print["  ESS unlabeled: ", Round[essU], " / ", sampleSize,
217	    " (", ToString[NumberForm[100. essU / sampleSize, {4, 2}]], "%)"];
218	  Print["  ESS facet    : ", Round[essF], " / ", sampleSize,
219	    " (", ToString[NumberForm[100. essF / sampleSize, {4, 2}]], "%)"]];
220	
221	Do[
222	  Print["-----------------------------------------"];
223	  Print["p = ", p, ", q = ", qVal, ", N = ", sampleSize,
224	    ", chunkSize = ", chunkSize, ", numChunks = ", numChunks];
225	
226	  If[FileExistsQ[finalStatsFile[p]] && FileExistsQ[finalComplexesFile[p]],
227	    Print["  final WXF files already present — skipping p = ", p],
228	   (* else *)
229	    Module[{startK = firstMissingChunk[p]},
230	      If[startK > 1, Print["  resuming at chunk ", startK, " / ", numChunks]];
231	
232	      Do[
233	        Module[{thisN = chunkSizeFor[k], tSample, tStats, sample,
234	                statsRows, numVs, auts, autFs, wV, wU, wF, rows},
235	          Print["  chunk ", k, "/", numChunks, " (n=", thisN, ")"];
236	          SeedRandom[randomSeed + runSeedOffset + p*1000 + k];
237	
238	          tSample = First @ AbsoluteTiming[
239	            sample = RandomVertexLabeledPureSimplicialComplex[{p, qVal}, thisN]];
240	          Print["    sampling : ", tSample, " s"];
241	
242	          tStats = First @ AbsoluteTiming[
243	            statsRows = If[useParallel,
244	              ParallelMap[statsFor[#, p] &, sample],
245	              statsFor[#, p] & /@ sample]];
246	          Print["    stats    : ", tStats, " s"];
247	
248	          numVs = statsRows[[All, 1]];
249	          auts  = statsRows[[All, 2]];
250	          autFs = statsRows[[All, 3]];
251	          wV = ConstantArray[1, thisN];
252	          wU = MapThread[#1 / #2! &, {auts, numVs}];
253	          wF = MapThread[#1 * qVal! / (#2 * #3!) &, {auts, autFs, numVs}];
254	          rows = MapThread[Join[#1, {#2, #3, #4}] &, {statsRows, wV, wU, wF}];
255	
256	          exportChunkAtomic[p, k, sample, rows];
257	          Print["    wrote chunk files"]],
258	        {k, startK, numChunks}];
259	
260	      reportESS[p, consolidateChunks[p]]]],
261	  {p, pList}];
262	
263	Print["-----------------------------------------"];
264	Print["Done."];
265

