(* Is `candidate` in the orbit of canonicalRemovalVSide[cmplx] under
   the automorphism group of bipartiteIncidenceGraph[cmplx]? Cheap
   short-circuit when candidate IS the canonical-removal vertex. *)
isInCanonicalRemovalOrbit[cmplx_List, candidate_String] := Module[
  {g, n, vLabels, canonRem, autGroup, vOrbits, hostOrbit},
