      localCount++;
    ];

    dfs[state_List, currTotal_Integer] := If[
      currTotal == target,
      emit[state],
      Do[
        With[{newState = Append[state, v]},
          If[isMcKayValid[newState],
            dfs[newState, currTotal + Length[v]]]],
        {v, addOneVertex[state]}]
    ];

    dfs[{v0}, Length[v0]];

